import{_ as a,o as t,c as s,ah as i}from"./chunks/framework.Sdx4l2LO.js";const h=JSON.parse('{"title":"DINOForge Proof of Features","description":"","frontmatter":{},"headers":[],"relativePath":"proof-of-features/README.md","filePath":"proof-of-features/README.md","lastUpdated":1774801192000}'),o={name:"proof-of-features/README.md"};function n(r,e,l,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="dinoforge-proof-of-features" tabindex="-1">DINOForge Proof of Features <a class="header-anchor" href="#dinoforge-proof-of-features" aria-label="Permalink to &quot;DINOForge Proof of Features&quot;">​</a></h1><p>Automated evidence bundles from feature validation runs using the v2 pipeline.</p><h2 id="bundle-structure" tabindex="-1">Bundle Structure <a class="header-anchor" href="#bundle-structure" aria-label="Permalink to &quot;Bundle Structure&quot;">​</a></h2><p>Each run of <code>/prove-features</code> creates a timestamped directory <code>YYYYMMDD_HHmmss/</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;timestamp&gt;/</span></span>
<span class="line"><span>  raw_mods.mp4            Raw 6s game clip — main menu with Mods button visible</span></span>
<span class="line"><span>  raw_f9.mp4              Raw 8s game clip — F9 debug overlay triggered</span></span>
<span class="line"><span>  raw_f10.mp4             Raw 8s game clip — F10 mod menu triggered</span></span>
<span class="line"><span>  validate_mods.png       VLM-confirmed screenshot (live GDI at time of Mods display)</span></span>
<span class="line"><span>  validate_f9.png         VLM-confirmed screenshot (live GDI at time of F9 display)</span></span>
<span class="line"><span>  validate_f10.png        VLM-confirmed screenshot (live GDI at time of F10 display)</span></span>
<span class="line"><span>  validate_report.json    Machine-readable: [{ feature, vlm_response, confirmed, timestamp }]</span></span>
<span class="line"><span>  mods_feature.mp4        Remotion-rendered 10s clip with spring-physics callout (green)</span></span>
<span class="line"><span>  f9_feature.mp4          Remotion-rendered 10s clip with spring-physics callout (yellow)</span></span>
<span class="line"><span>  f10_feature.mp4         Remotion-rendered 10s clip with spring-physics callout (blue)</span></span>
<span class="line"><span>  dinoforge_reel.mp4      38s compilation reel — primary deliverable</span></span>
<span class="line"><span>  proof_report.md         Human-readable summary with validation table and render status</span></span></code></pre></div><h2 id="pipeline-v2" tabindex="-1">Pipeline (v2) <a class="header-anchor" href="#pipeline-v2" aria-label="Permalink to &quot;Pipeline (v2)&quot;">​</a></h2><h3 id="phase-1-capture-scripts-game-capture-feature-clips-ps1" tabindex="-1">Phase 1: Capture (<code>scripts/game/capture-feature-clips.ps1</code>) <a class="header-anchor" href="#phase-1-capture-scripts-game-capture-feature-clips-ps1" aria-label="Permalink to &quot;Phase 1: Capture (\`scripts/game/capture-feature-clips.ps1\`)&quot;">​</a></h3><ul><li>Game launched fresh, all instances killed first</li><li>Boot wait: polls <code>dinoforge_debug.log</code> for <code>&quot;Awake completed&quot;</code> (Stage A, 30s)</li><li>Menu wait: polls <code>LogOutput.log</code> for <code>&quot;MODS BUTTON INJECTION FULLY SUCCESSFUL&quot;</code> (Stage B, 720s)</li><li>Capture: <code>ffmpeg -f gdigrab -i &quot;title=Diplomacy is Not an Option&quot;</code> — NOT <code>-i desktop</code></li><li>Key injection: Win32 <code>SendInput</code> via C# <code>Add-Type</code> — works without window focus</li><li>Resolution: all clips normalized to 1280×800 via <code>-vf scale=1280:800</code></li></ul><h3 id="vlm-validation-gate-orchestrated-in-claude-session" tabindex="-1">VLM Validation Gate (orchestrated in Claude session) <a class="header-anchor" href="#vlm-validation-gate-orchestrated-in-claude-session" aria-label="Permalink to &quot;VLM Validation Gate (orchestrated in Claude session)&quot;">​</a></h3><ul><li>After each clip: <code>game_analyze_screen</code> MCP takes a <strong>live GDI screenshot</strong> of the game window</li><li>Game remains running and in correct UI state during validation</li><li>Retry once on failure; second failure exits non-zero and deletes the unvalidated clip</li><li>Results written to <code>validate_report.json</code> with <code>confirmed: true/false</code></li></ul><h3 id="phase-2-tts-scripts-video-generate-tts-py" tabindex="-1">Phase 2: TTS (<code>scripts/video/generate_tts.py</code>) <a class="header-anchor" href="#phase-2-tts-scripts-video-generate-tts-py" aria-label="Permalink to &quot;Phase 2: TTS (\`scripts/video/generate_tts.py\`)&quot;">​</a></h3><ul><li>Reads <code>scripts/video/vo_spec.json</code> (5 line items)</li><li>Generates 5 MP3s via <code>edge-tts</code> en-US-AriaNeural (Microsoft Edge neural voice — free)</li><li>File-based approach avoids PowerShell <code>ArgumentList</code> arg-splitting bug from v1</li></ul><h3 id="phase-3-composition-scripts-video-—-remotion-project" tabindex="-1">Phase 3: Composition (<code>scripts/video/</code> — Remotion project) <a class="header-anchor" href="#phase-3-composition-scripts-video-—-remotion-project" aria-label="Permalink to &quot;Phase 3: Composition (\`scripts/video/\` — Remotion project)&quot;">​</a></h3><ul><li><code>CalloutBox</code>: spring-physics scale-in (<code>damping: 12, stiffness: 180</code>) — natural overshoot</li><li><code>FeatureScene</code>: raw clip + TTS audio + callout + caption bar, with freeze-frame padding</li><li>Individual clips: 300 frames (10s) each — 6-8s source + freeze-frame remainder</li><li>Compilation reel: 1140 frames (38s): 3s intro + 10s×3 features + 5s outro</li><li>Output: H.264 baseline, yuv420p, AAC 128k, <code>faststart</code></li></ul><h2 id="color-coding" tabindex="-1">Color Coding <a class="header-anchor" href="#color-coding" aria-label="Permalink to &quot;Color Coding&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Color</th><th>Hex</th></tr></thead><tbody><tr><td>Mods Button</td><td>Green</td><td><code>#34d399</code></td></tr><tr><td>F9 Debug Overlay</td><td>Yellow</td><td><code>#fbbf24</code></td></tr><tr><td>F10 Mod Menu</td><td>Blue</td><td><code>#60a5fa</code></td></tr></tbody></table><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># From repo root:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prove</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">features</span></span></code></pre></div><h2 id="legacy-files" tabindex="-1">Legacy Files <a class="header-anchor" href="#legacy-files" aria-label="Permalink to &quot;Legacy Files&quot;">​</a></h2><p>Files in this directory without a timestamp subfolder are from the v1 pipeline (pre-2026-03-27) and are kept for reference. The v1 pipeline had three known defects:</p><ol><li>gdigrab used <code>-i desktop</code> — captured the Claude Code terminal, not the game</li><li>edge-tts arg-splitting via PowerShell <code>ArgumentList</code> fell back to SAPI (90s-era voice)</li><li>No VLM validation — blank or wrong captures counted as proof</li></ol>`,21)])])}const f=a(o,[["render",n]]);export{h as __pageData,f as default};
